import{_ as e,a,o as n,a4 as i}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse(`{"title":"Create Transaction","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-transactions-create","title":"Create Transaction","description":"Record a full or partial payment against an invoice. Returns the created transaction. When the recorded payments reach the invoice total the invoice is marked paid and the order status advances.","query":"curl -X POST \\"https://your-domain.com/api/admin/transactions\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -d '{\\n    \\"invoiceId\\": 12,\\n    \\"paymentMethod\\": \\"cashondelivery\\",\\n    \\"amount\\": 100\\n  }'\\n","response":"{\\n  \\"id\\": 5,\\n  \\"transactionId\\": \\"8f2c1a7b9d0e4f6a3c5b8d1e2f7a9c0b4d6e8f10\\",\\n  \\"invoiceId\\": 12,\\n  \\"orderId\\": 8,\\n  \\"orderIncrementId\\": \\"00000000008\\",\\n  \\"amount\\": 100,\\n  \\"formattedAmount\\": \\"$100.00\\",\\n  \\"status\\": \\"paid\\",\\n  \\"type\\": \\"cashondelivery\\",\\n  \\"paymentMethod\\": \\"cashondelivery\\",\\n  \\"paymentTitle\\": \\"Cash On Delivery\\",\\n  \\"data\\": { \\"paidAmount\\": 100 },\\n  \\"createdAt\\": \\"2026-06-30 10:15:00\\",\\n  \\"updatedAt\\": \\"2026-06-30 10:15:00\\",\\n  \\"order\\": {\\n    \\"id\\": 8,\\n    \\"incrementId\\": \\"00000000008\\",\\n    \\"status\\": \\"processing\\",\\n    \\"customerName\\": \\"John Doe\\",\\n    \\"customerEmail\\": \\"john.doe@example.com\\",\\n    \\"grandTotal\\": 100,\\n    \\"orderCurrencyCode\\": \\"USD\\"\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/sales/transactions/create.md","filePath":"api/rest-api/admin/sales/transactions/create.md","lastUpdated":1783079210000}`),o={name:"api/rest-api/admin/sales/transactions/create.md"};function d(r,t,s,c,h,l){return n(),a("div",null,t[0]||(t[0]=[i(`<h1 id="create-transaction" tabindex="-1">Create Transaction <a class="header-anchor" href="#create-transaction" aria-label="Permalink to &quot;Create Transaction&quot;">​</a></h1><p>The API equivalent of the admin <strong>Sales → Transactions → Create</strong> (&quot;Record Payment&quot;) action. Records a manual payment against an invoice and returns the created transaction, which then appears in the <a href="/api/rest-api/admin/sales/transactions/list.html">Transactions listing</a>.</p><p>Partial payments are supported. Once the cumulative recorded payments for an invoice reach its grand total, the invoice is marked <strong>paid</strong> and the order advances to <strong>completed</strong> (when it already has a shipment) or <strong>processing</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Two ways to create a transaction</p><p>This endpoint records an <strong>arbitrary or partial</strong> payment you specify (invoice, method, amount). Alternatively, the <strong>Create Transaction</strong> checkbox on <a href="/api/rest-api/admin/sales/orders/create-invoice.html">invoice creation</a> captures the <strong>full</strong> invoice amount in one step using the order&#39;s payment method. Both result in a transaction that appears in the Transactions listing.</p></div><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/transactions</code></td><td>POST</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>invoiceId</code></td><td>integer</td><td>Yes</td><td>The invoice to record the payment against.</td></tr><tr><td><code>paymentMethod</code></td><td>string</td><td>Yes</td><td>Payment method code (e.g. <code>cashondelivery</code>, <code>moneytransfer</code>).</td></tr><tr><td><code>amount</code></td><td>number</td><td>Yes</td><td>Amount paid. Must be greater than <code>0</code> and cannot push the invoice&#39;s cumulative payments above its grand total.</td></tr></tbody></table><h2 id="response-fields" tabindex="-1">Response fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>Integer</td><td>The created transaction row id.</td></tr><tr><td><code>transactionId</code></td><td>String</td><td>Generated transaction reference.</td></tr><tr><td><code>invoiceId</code></td><td>Integer</td><td>The invoice this payment was recorded against.</td></tr><tr><td><code>orderId</code> / <code>orderIncrementId</code></td><td>Integer / String</td><td>Parent order id and human-facing number.</td></tr><tr><td><code>amount</code> / <code>formattedAmount</code></td><td>Number / String</td><td>Recorded amount, raw and formatted.</td></tr><tr><td><code>status</code></td><td>String</td><td>Always <code>paid</code> for a recorded payment.</td></tr><tr><td><code>type</code> / <code>paymentMethod</code></td><td>String</td><td>The payment method code used.</td></tr><tr><td><code>paymentTitle</code></td><td>String</td><td>Human-readable payment method title.</td></tr><tr><td><code>data</code></td><td>Object</td><td>Recorded payment payload — <code>{ &quot;paidAmount&quot;: &lt;amount&gt; }</code>.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>String</td><td>Timestamps.</td></tr><tr><td><code>order</code></td><td>Object</td><td>Slim order summary — <code>id</code>, <code>incrementId</code>, <code>status</code>, <code>customerName</code>, <code>customerEmail</code>, <code>grandTotal</code>, <code>orderCurrencyCode</code>.</td></tr></tbody></table><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>When</th></tr></thead><tbody><tr><td><code>422</code></td><td><code>invoiceId</code>, <code>paymentMethod</code>, or <code>amount</code> is missing, or <code>amount</code> is not numeric.</td></tr><tr><td><code>400</code></td><td>Unknown invoice, the invoice is already fully paid, <code>amount</code> ≤ 0, or the amount would exceed the invoice grand total.</td></tr><tr><td><code>401</code></td><td>Missing or invalid admin token.</td></tr><tr><td><code>403</code></td><td>Admin role lacks the required permission.</td></tr></tbody></table><h2 id="creating-a-transaction-while-invoicing-the-create-transaction-checkbox" tabindex="-1">Creating a transaction while invoicing (the &quot;Create Transaction&quot; checkbox) <a class="header-anchor" href="#creating-a-transaction-while-invoicing-the-create-transaction-checkbox" aria-label="Permalink to &quot;Creating a transaction while invoicing (the &quot;Create Transaction&quot; checkbox)&quot;">​</a></h2><p>On the order detail page, the admin invoice form has a <strong>Create Transaction</strong> checkbox. Ticking it records the payment automatically at the moment the invoice is created — you don&#39;t call this endpoint at all.</p><p>The API equivalent is <strong>not</strong> a separate transaction call: it&#39;s a single flag on <a href="/api/rest-api/admin/sales/orders/create-invoice.html">Create Invoice</a>. Send <code>can_create_transaction: true</code> in the invoice-create body and the invoice&#39;s <strong>full</strong> amount is recorded as a transaction against the order&#39;s payment method in the same request:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://your-domain.com/api/admin/orders/8/invoices&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;token&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Accept: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;items&quot;: [ { &quot;orderItemId&quot;: 42, &quot;quantity&quot;: 1 } ],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;can_create_transaction&quot;: true</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p>The resulting transaction then appears in the <a href="/api/rest-api/admin/sales/transactions/list.html">Transactions listing</a>, exactly like one created through this endpoint.</p><p><strong>Which to use:</strong></p><table tabindex="0"><thead><tr><th>You want to…</th><th>Use</th></tr></thead><tbody><tr><td>Record the <strong>full</strong> invoice amount at invoice time (one step)</td><td><a href="/api/rest-api/admin/sales/orders/create-invoice.html">Create Invoice</a> with <code>can_create_transaction: true</code></td></tr><tr><td>Record a <strong>partial</strong> payment, a <strong>later</strong> payment, or a specific <strong>amount/method</strong> against an existing invoice</td><td><strong>This endpoint</strong> (<code>POST /api/admin/transactions</code>)</td></tr></tbody></table><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>sales.transactions.view</code></p>`,21)]))}const u=e(o,[["render",d]]);export{m as __pageData,u as default};
